// ---------- hooks, map, budget ----------
// Expected wiring: each event runs its script for the listed tools. Hooks use exec form
// (command "node", the script path as the only argument, located through the
// ${CLAUDE_PROJECT_DIR} placeholder that Claude Code substitutes without a shell).
// Only PreToolUse enforcement is critical and fails closed (onFailure "block").
// PostToolUseFailure re-checks the effects of failed shell commands.
const HOOKS = {
  PreToolUse: { script: '.claude/hooks/pre-tool-use.js', tools: ['Bash', 'PowerShell'], failClosed: true },
  PostToolUse: { script: '.claude/hooks/post-tool-use.js', tools: ['Write', 'Edit', 'MultiEdit', 'Bash', 'PowerShell'], failClosed: false },
  PostToolUseFailure: { script: '.claude/hooks/post-tool-use.js', tools: ['Bash', 'PowerShell'], failClosed: false },
  Stop: { script: '.claude/hooks/stop.js', tools: null, failClosed: false },
};

function checkHookHandler(file, event, spec, hook) {
  const where = `${event} hook`;
  if (hook.type !== 'command') add('ERROR', file, `${where}: type must be "command".`);
  if (hook.command !== 'node') add('ERROR', file, `${where}: use exec form — command "node" with the script in args (found command ${JSON.stringify(hook.command)}).`);
  const script = hookScript(hook);
  if (!script) {
    add('ERROR', file, `${where}: args must be exactly ["\${CLAUDE_PROJECT_DIR}/.claude/hooks/<script>.js"] (found ${JSON.stringify(hook.args)}).`);
  } else if (!common.exists(script)) {
    add('ERROR', file, `${where}: script missing: ${script}`);
  }
  if (spec.failClosed && hook.onFailure !== 'block') {
    add('ERROR', file, `${where}: critical pre-tool enforcement must fail closed (onFailure: "block").`);
  }
  if (!spec.failClosed && hook.onFailure !== undefined) {
    add('ERROR', file, `${where}: onFailure is reserved for the critical PreToolUse enforcement; post-change and Stop hooks report failures visibly without blocking (on Stop it has no effect).`);
  }
}

function checkMap(files) {
  const mapFile = '.claude/MAP.md';
  if (!common.exists(mapFile)) {
    add('ERROR', mapFile, 'human map missing.');
    return;
  }
  const map = common.readText(mapFile);
  const listed = [...files, ...enforcementFiles(), ...ROOT_CONFIG.filter((f) => common.exists(f)), 'SPECIFICATION.md', 'CUSTOM_SETTINGS.md'];
  for (const f of listed) {
    if (f === mapFile) continue;
    const short = f.replace(/^\.claude\//, '');
    if (!map.includes(f) && !map.includes(short)) add('ERROR', mapFile, `map does not list ${f}`);
  }
}
